#!/usr/bin/env bash
set -Eeuo pipefail
B="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"; ns=devops-portfolio; release=operaciones1-guia10; cluster=operaciones1; port=${K3D_INGRESS_PORT:-$([[ ${OPERACIONES_GLOBAL:-0} == 1 ]] && echo 18010 || echo 8090)}
start(){ k3d cluster list -o json | jq -e --arg n "$cluster" '.[]|select(.name==$n)' >/dev/null || k3d cluster create "$cluster" --servers 1 --agents 1 -p "127.0.0.1:8089:30089@agent:0" -p "127.0.0.1:18009:30089@agent:0" -p "127.0.0.1:8090:80@loadbalancer" -p "127.0.0.1:18010:80@loadbalancer" --wait; docker build -t operaciones1-guia10-backend:local "$B/backend"; docker build -t operaciones1-guia10-frontend:local "$B/frontend"; k3d image import -c "$cluster" operaciones1-guia10-backend:local operaciones1-guia10-frontend:local; helm repo add ingress-nginx https://kubernetes.github.io/ingress-nginx --force-update >/dev/null; helm repo update >/dev/null; helm upgrade --install ingress-nginx ingress-nginx/ingress-nginx -n ingress-nginx --create-namespace --set controller.service.type=LoadBalancer --set controller.ingressClassResource.default=true --wait --timeout 5m; helm upgrade --install "$release" "$B/devops-portfolio" -f "$B/values-dev.yaml" --set backend.image.repository=operaciones1-guia10-backend --set backend.image.tag=local --set backend.image.pullPolicy=IfNotPresent --set frontend.image.repository=operaciones1-guia10-frontend --set frontend.image.tag=local --set frontend.image.pullPolicy=IfNotPresent --wait --timeout 5m; }
case ${1:-} in iniciar) start;; detener) if helm status "$release" >/dev/null 2>&1; then helm uninstall "$release"; fi;; reiniciar) "$0" detener; start;; estado) if helm status "$release" >/dev/null 2>&1; then helm status "$release"; else echo 'Guía 10: NO DESPLEGADA'; fi;; verificar) RELEASE="$release" K3D_INGRESS_PORT="$port" INGRESS_HOST="devops-portfolio.dev" "$B/scripts/verificar.sh";; logs) kubectl logs -n "$ns" deployment/backend --tail=100;; *) exit 64;; esac
